 "additionalProperties": false,
 "required": [
 "CurrencyOfTransfer"
 ],
 "properties": {
 "InstructionPriority": {
 "description": "Indicator of the urgency or order of importance that the instructing party would like the instructed party to apply to the processing of the instruction.",
 "type": "string",
